from fastapi import FastAPI
from pydantic import BaseModel
import sqlite3
import os

app = FastAPI()
port = int(os.getenv('PORT', 3000))

db = sqlite3.connect(':memory:', check_same_thread=False)
db.executescript('PRAGMA foreign_keys = ON')
db.executescript('''CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL)''')
db.executescript('''CREATE TABLE IF NOT EXISTS posts (id INTEGER PRIMARY KEY, title TEXT NOT NULL, body TEXT, user_id INTEGER NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id))''')

class UserBody(BaseModel):
    name: str
    email: str

class PostBody(BaseModel):
    title: str
    body: str
    user_id: int

@app.get('/health')
def health():
    return {'status': 'ok'}

@app.post('/users', status_code=201)
def create_user(body: UserBody):
    cursor = db.execute('INSERT INTO users (name, email) VALUES (?, ?)', (body.name, body.email))
    db.commit()
    return {'id': cursor.lastrowid, 'name': body.name, 'email': body.email}

@app.post('/posts', status_code=201)
def create_post(body: PostBody):
    cursor = db.execute('INSERT INTO posts (title, body, user_id) VALUES (?, ?, ?)', (body.title, body.body, body.user_id))
    db.commit()
    return {'id': cursor.lastrowid, 'title': body.title, 'body': body.body, 'user_id': body.user_id}

