package main

import (
	"database/sql"
	"encoding/json"
	"net/http"
	"os"
	"strconv"
	"strings"

	_ "github.com/mattn/go-sqlite3"
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	db, _ := sql.Open("sqlite3", ":memory:")
	db.Exec("PRAGMA foreign_keys = ON")
	db.Exec(`CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, name TEXT NOT NULL, email TEXT NOT NULL)`)
	db.Exec(`CREATE TABLE IF NOT EXISTS posts (id INTEGER PRIMARY KEY, title TEXT NOT NULL, body TEXT, user_id INTEGER NOT NULL, FOREIGN KEY (user_id) REFERENCES users(id))`)

	http.HandleFunc("/health", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]string{"status": "ok"})
	})

	http.HandleFunc("/users", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method == "POST" {
			var body struct { Name string `json:"name"`; Email string `json:"email"` }
			json.NewDecoder(r.Body).Decode(&body)
			result, _ := db.Exec("INSERT INTO users (name, email) VALUES (?, ?)", body.Name, body.Email)
			id, _ := result.LastInsertId()
			w.WriteHeader(http.StatusCreated)
			json.NewEncoder(w).Encode(map[string]interface{}{"id": id, "name": body.Name, "email": body.Email})
		}
	})

	http.HandleFunc("/posts", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if r.Method == "POST" {
			var body struct { Title string `json:"title"`; Body string `json:"body"`; UserID int `json:"user_id"` }
			json.NewDecoder(r.Body).Decode(&body)
			result, _ := db.Exec("INSERT INTO posts (title, body, user_id) VALUES (?, ?, ?)", body.Title, body.Body, body.UserID)
			id, _ := result.LastInsertId()
			w.WriteHeader(http.StatusCreated)
			json.NewEncoder(w).Encode(map[string]interface{}{"id": id, "title": body.Title, "body": body.Body, "user_id": body.UserID})
		}
	})

	http.HandleFunc("/users/", func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Content-Type", "application/json")
		if strings.HasSuffix(r.URL.Path, "/posts") {
			parts := strings.Split(strings.TrimPrefix(r.URL.Path, "/users/"), "/")
			id, _ := strconv.Atoi(parts[0])
			rows, _ := db.Query("SELECT posts.id, posts.title, posts.body, posts.user_id, users.name as author FROM posts JOIN users ON posts.user_id = users.id WHERE users.id = ?", id)
			var posts []map[string]interface{}
			for rows.Next() {
				var id, userID int
				var title, body, author string
				rows.Scan(&id, &title, &body, &userID, &author)
				posts = append(posts, map[string]interface{}{"id": id, "title": title, "body": body, "user_id": userID, "author": author})
			}
			json.NewEncoder(w).Encode(posts)
		}
	})

	http.ListenAndServe(":"+port, nil)
}

